async function request(url,options={},asText=false){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),options.timeout||30000);try{const response=await fetch(url,{...options,signal:controller.signal}),text=await response.text();let data=text;if(!asText){try{data=text?JSON.parse(text):{};}catch{throw new Error(`服务返回非 JSON 数据（HTTP ${response.status}），请检查本地服务日志`);}}if(!response.ok)throw new Error((typeof data==='object'&&(data.error||data.message))||`请求失败（HTTP ${response.status}）`);return data;}catch(error){if(error.name==='AbortError')throw new Error('请求超时。请检查本地服务状态后重试；已提交的任务可从运行记录查看。');throw error;}finally{clearTimeout(timer);}}
