function updateButtons(){for(const id of ['#run-simulation','#run-pointcloud','#run-batch','#validate-config'])$(id).disabled=!workspace||submitBusy||uploadBusy>0;}
function busy(button,fn){return async(...args)=>{if(button.disabled)return;const text=button.textContent;button.disabled=true;try{return await fn(...args);}catch(error){message('#global-message',error.message,true);}finally{button.disabled=false;button.textContent=text;updateButtons();}};}
function scopeLabel(scope){if(Array.isArray(scope))return scope.map(scopeLabel).join(' / ');if(scope&&typeof scope==='object')return JSON.stringify(scope);return {both:'单 / 多阶段',all:'通用',single:'单阶段',staged:'多阶段',strict:'严格模式',fast:'高速模式',postprocess:'后处理',inactive:'当前流程未使用',pointcloud:'点云处理'}[scope]||scope||'通用';}
