function pointcloudChart(sample){if(!Array.isArray(sample)||sample.length<2)return '';const points=sample.filter(point=>Array.isArray(point)&&point.length>=3&&point.slice(0,3).every(value=>typeof value==='number'&&Number.isFinite(value))).slice(0,1000);if(!points.length)return '';const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),zs=points.map(p=>p[2]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),minZ=Math.min(...zs),maxZ=Math.max(...zs),x=p=>45+(p-minX)/(maxX-minX||1)*325,y=p=>150-(p-minY)/(maxY-minY||1)*125;return `<svg class="scatter-chart" viewBox="0 0 400 185" role="img" aria-label="上传点云实际抽样点的 XY 投影，颜色表示 Z"><path d="M45 20V150H370" stroke="#cbd9c0" fill="none"/>${points.map(point=>{const ratio=(point[2]-minZ)/(maxZ-minZ||1);return `<circle cx="${x(point[0]).toFixed(2)}" cy="${y(point[1]).toFixed(2)}" r="1.5" fill="hsl(${(165-ratio*75).toFixed(0)} 35% ${(50-ratio*17).toFixed(0)}%)" opacity=".75"/>`;}).join('')}<text x="45" y="169" fill="#829573" font-size="9">${format(minX)} mm</text><text x="350" y="169" fill="#829573" font-size="9" text-anchor="end">${format(maxX)} mm</text><text x="210" y="182" fill="#607954" font-size="9">X / mm · 颜色表示 Z</text><text x="5" y="24" fill="#829573" font-size="9">Y / mm</text></svg><small>文件真实抽样 ${points.length} 点的 XY 投影</small>`;}
async function inspectTarget(){if(!workspace.targetUpload)return;const url=new URL(`/api/uploads/${encodeURIComponent(workspace.targetUpload.id)}/inspect`,location.origin);url.searchParams.set('kind','target');url.searchParams.set('orientation',workspace.targetOrientation);if(workspace.targetVariable)url.searchParams.set('variable',workspace.targetVariable);const data=await request(url),variables=data.variables||[],select=$('#target-variable');select.innerHTML=`<option value="">${variables.length?'请选择数值变量':'文本表格（无需选择变量）'}</option>`+variables.map(item=>`<option value="${escape(item.name)}">${escape(item.name)} · ${(item.shape||[]).join(' × ')}</option>`).join('');if(data.selected){workspace.targetVariable=data.selected;select.value=data.selected;}else select.value=workspace.targetVariable;select.disabled=!variables.length;workspace.targets=clone(data.targets||data.preview?.targets||[]);$('#targets').value=JSON.stringify(workspace.targets,null,2);workspace.simulation.ACTIVE_STAGE_TARGET_DATA=clone(workspace.targets);if(workspace.targets.length&&workspace.runMode==='single')workspace.simulation.SINGLE_STAGE_TARGET_DATA=clone(workspace.targets[0]);$('#target-table').innerHTML=targetTable(workspace.targets);$('#target-file-options').hidden=false;const issues=data.issues||[];workspace.targetIssues=clone(issues);$('#target-preview').innerHTML=`<strong>${escape(workspace.targetUpload.name)}</strong> · ${escape(data.selected||workspace.targetVariable||'六列表格')} · 原始尺寸 ${escape((data.original_shape||data.shape||variables.find(item=>item.name===workspace.targetVariable)?.shape||[]).join(' × '))}<br>已读取 ${workspace.targets.length} 个阶段${data.transposed?'（已转置）':''}。${data.reading_seconds!=null?`读取 ${seconds(data.reading_seconds)}。`:''}${issues.length?`<p class="error-hint">${issues.map(item=>escape(typeof item==='string'?item:item.message||JSON.stringify(item))).join('；')}</p>`:''}`;syncTargetSource();invalidatePrecheck();renderCatalog('simulation');}
async function uploadTarget(input){const file=input.files[0];if(!file)return;uploadBusy++;updateButtons();workspace.targetUpload=null;workspace.targetIssues=[];workspace.targets=[];$('#target-preview').textContent='正在上传并解析六指标目标…';try{workspace.targetUpload=await upload(file);workspace.targetVariable='';workspace.targetOrientation='auto';workspace.transferGeometry=null;$('#target-orientation').value='auto';await inspectTarget();message('#sim-message','目标文件已读取，请确认变量、方向、指标单位与阶段方式。');}catch(error){message('#sim-message',error.message,true);$('#target-preview').textContent=error.message;workspace.targets=[];$('#targets').value='[]';$('#target-table').innerHTML='';}finally{uploadBusy--;updateButtons();}}
async function submitSimulation(){submitBusy=true;updateButtons();message('#sim-message','正在检查配置和资源…');try{const payload=collectSimulation(true);await checkConfig(payload);const job=await post('/api/jobs',payload);await openJob(job.id,job);message('#sim-message',`任务已提交：${job.id}；本次种子 ${workspace.simulation.GA_CONFIG.seed}。`);refreshHistory();}catch(error){message('#sim-message',error.message,true);}finally{submitBusy=false;updateButtons();}}
async function submitPointcloud(){submitBusy=true;updateButtons();try{commitCatalog('pointcloud');const payload=pointcloudPayload(workspace,uploads.reference?.id,uploads.detail?.id);message('#pointcloud-message','正在提交 MATLAB 任务…');const job=await post('/api/jobs',payload);await openJob(job.id,job);message('#pointcloud-message',`点云任务已提交：${job.id}。`);refreshHistory();}catch(error){message('#pointcloud-message',error.message,true);}finally{submitBusy=false;updateButtons();}}
function syncTargetSource(){if('TARGET_SOURCE' in workspace.simulation)workspace.simulation.TARGET_SOURCE=workspace.targetUpload?'matlab':'manual';}
function syncBatchControls(){const config=workspace.simulation.MULTI_CASE_CONFIG;if(config){workspace.batchMode=config.run_mode;workspace.parallelCaseWorkers=config.parallel_case_workers;workspace.sequentialEnabled=config.sequential_enabled;workspace.parallelEnabled=config.parallel_enabled;}$('#batch-mode').value=workspace.batchMode;$('#parallel-case-workers').value=workspace.parallelCaseWorkers;$('#sequential-enabled').checked=workspace.sequentialEnabled;$('#parallel-enabled').checked=workspace.parallelEnabled;updateBatchAvailability();}
function updateBatchAvailability(){const mixed=$('#batch-mode').value==='mixed';$('#sequential-enabled').disabled=!mixed;$('#parallel-enabled').disabled=!mixed;$('#parallel-case-workers').disabled=['single','sequential'].includes($('#batch-mode').value);}
function syncBatchConfig(){const config=workspace.simulation.MULTI_CASE_CONFIG;if(!config)return;Object.assign(config,{run_mode:workspace.batchMode,parallel_case_workers:workspace.parallelCaseWorkers,sequential_enabled:workspace.sequentialEnabled,parallel_enabled:workspace.parallelEnabled});if(workspace.cases.length)config.cases=workspace.cases.map(({source_name,target_issues,...item})=>clone(item));}
function renderCases(){const list=$('#case-list');if(!workspace.cases.length){list.innerHTML='<div class="empty-state small">尚未添加工况。配置当前目标后，点击“添加当前目标为工况”。</div>';return;}list.innerHTML=workspace.cases.map((item,index)=>`<div class="case-row"><div class="field"><label for="case-name-${index}">工况 ${index+1} 名称</label><input id="case-name-${index}" data-case-name="${index}" value="${escape(item.case_name)}"></div><div class="field case-mode"><label for="case-mode-${index}">阶段方式</label><select id="case-mode-${index}" data-case-mode="${index}"><option value="single" ${item.simulation_mode==='single'?'selected':''}>单阶段</option><option value="staged" ${item.simulation_mode!=='single'?'selected':''}>多阶段</option></select></div><button class="button ghost remove-case" data-remove-case="${index}" aria-label="移除工况 ${index+1}">移除</button><div class="field"><label for="case-group-${index}">混合调度分组</label><select id="case-group-${index}" data-case-group="${index}"><option value="sequential" ${item.mode!=='parallel'?'selected':''}>串行组（先运行）</option><option value="parallel" ${item.mode==='parallel'?'selected':''}>并行组（后运行）</option></select></div><div class="field case-targets"><label for="case-targets-${index}">工况六指标目标（JSON）</label><textarea id="case-targets-${index}" data-case-targets="${index}" rows="3" spellcheck="false">${escape(JSON.stringify(item.targets||[],null,2))}</textarea></div><div class="case-source">${escape(item.source_name||item.matlab_target||'目标矩阵独立快照')} · 独立目标快照${item.matlab_target&&!item.targets?'；本机路径需要先在目标区导入文件，再填写有效矩阵':''}</div></div>`).join('');list.querySelectorAll('[data-remove-case]').forEach(button=>button.addEventListener('click',()=>{workspace.cases.splice(Number(button.dataset.removeCase),1);syncBatchConfig();renderCases();renderCatalog('simulation');}));}
function readCases(requireRunnable=false){workspace.cases=workspace.cases.map((item,index)=>updateCaseDraft(item,{case_name:$(`#case-name-${index}`).value,simulation_mode:$(`#case-mode-${index}`).value,mode:$(`#case-group-${index}`).value,targets_text:$(`#case-targets-${index}`).value},requireRunnable));syncBatchConfig();}
function ensureBatchActions(id,state){let actions=$('#batch-actions');if(!actions){actions=document.createElement('div');actions.id='batch-actions';actions.className='actions';const stop=document.createElement('button');stop.id='stop-batch';stop.className='button danger';stop.textContent='停止整批';const retry=document.createElement('button');retry.id='retry-batch';retry.className='button secondary';retry.textContent='重试失败工况';const download=document.createElement('a');download.id='download-batch';download.className='button secondary';download.textContent='下载批次 ZIP';download.download='';actions.append(stop,retry,download);$('#batch-status').after(actions);stop.addEventListener('click',busy(stop,async()=>{await post(`/api/batches/${encodeURIComponent(currentBatchId)}/stop`);await pollBatch();refreshHistory();}));retry.addEventListener('click',busy(retry,async()=>{const result=await post(`/api/batches/${encodeURIComponent(currentBatchId)}/retry-failed`);message('#sim-message',result.retried_job_ids?.length?`已重试 ${result.retried_job_ids.length} 个有完整检查点的工况。`:'没有可安全恢复的失败工况。');await pollBatch();refreshHistory();}));}actions.hidden=!id;const stop=$('#stop-batch'),retry=$('#retry-batch'),download=$('#download-batch');stop.hidden=!id||isTerminal(state)||state==='needs_attention';retry.hidden=!id||!['needs_attention','failed','stopped'].includes(state);download.href=id?`/api/batches/${encodeURIComponent(id)}/download`:'#';download.download=id?`corrosion-batch-${id}.zip`:'';}
async function submitBatch(){submitBusy=true;updateButtons();try{collectSimulation(false);readCases(true);workspace.batchMode=$('#batch-mode').value;workspace.parallelCaseWorkers=parseTyped($('#parallel-case-workers').value,'integer');workspace.sequentialEnabled=$('#sequential-enabled').checked;workspace.parallelEnabled=$('#parallel-enabled').checked;syncBatchConfig();const payload=prepareBatch(workspace);if(payload.run_mode==='mixed'&&!payload.sequential_enabled&&!payload.parallel_enabled)throw new Error('混合调度至少启用串行或并行一种方式');await checkConfig({config:payload.config,run_mode:workspace.runMode,targets:workspace.targets});message('#sim-message','正在提交多工况…');const result=await post('/api/batches',payload),batch=result.batch||result;currentBatchId=batch.id;const jobs=result.jobs||batch.jobs||[];$('#batch-status').textContent=`批次 ${batch.id} 已提交，共 ${jobs.length||workspace.cases.length} 个工况。全局同时运行最多 2 个任务。`;ensureBatchActions(batch.id,batch.state);if(currentBatchId)pollBatch();refreshHistory();if(jobs.length){const first=typeof jobs[0]==='string'?jobs[0]:jobs[0].id;await openJob(first,typeof jobs[0]==='object'?jobs[0]:null);}message('#sim-message',`多工况已提交：${batch.id}。`);}catch(error){message('#sim-message',error.message,true);}finally{submitBusy=false;updateButtons();}}
async function pollBatch(){clearTimeout(batchTimer);const id=currentBatchId;if(!id)return;try{const batch=await request(`/api/batches/${encodeURIComponent(id)}`);if(currentBatchId!==id)return;const jobs=batch.jobs||batch.job_ids||[],completed=jobs.filter(item=>item.state==='completed').length||batch.completed_count||0;$('#batch-status').textContent=`批次 ${id} · ${statuses[batch.state]||batch.state||'调度中'} · 完成 ${completed} / ${jobs.length||batch.total||workspace.cases.length}${batch.actual_parallel_limit?' · 实际并发上限 '+batch.actual_parallel_limit:''}`;ensureBatchActions(id,batch.state);if(!isTerminal(batch.state)&&batch.state!=='needs_attention')batchTimer=setTimeout(pollBatch,2500);}catch(error){$('#batch-status').textContent=`批次状态读取失败：${error.message}。运行记录仍可查看各工况。`;}}
function downloadUrl(id,file){return `/api/jobs/${encodeURIComponent(id)}/download/${String(file).split('/').map(encodeURIComponent).join('/')}`;}
function checkpointAvailable(job){const checkpoint=job.checkpoint;return job.can_resume===true||job.resumable===true||checkpoint===true||(checkpoint&&typeof checkpoint==='object'&&(checkpoint.available===true||checkpoint.can_resume===true||checkpoint.resumable===true));}
function elapsed(job){if(job.elapsed_seconds!=null)return seconds(job.elapsed_seconds);if(job.state==='running'&&job.started_at)return seconds(Date.now()/1000-job.started_at);return '等待服务端计时';}
async function openJob(id,initial=null){clearTimeout(pollTimer);pollToken++;currentJobId=id;pollErrors=0;activate('results-panel');message('#job-message','');$('#job-empty').hidden=true;$('#job-body').hidden=false;$('#result-content').innerHTML='';$('#job-log').textContent='正在读取本次日志…';try{const job=initial&&initial.state?initial:await request(`/api/jobs/${encodeURIComponent(id)}`);if(currentJobId!==id)return;showJob(job);if(!isTerminal(job.state))schedulePoll(pollToken);await loadLog(id);}catch(error){message('#job-message',error.message,true);$('#result-state').textContent='读取失败';}}
function schedulePoll(token){clearTimeout(pollTimer);pollTimer=setTimeout(async()=>{const id=currentJobId;if(!id||token!==pollToken)return;try{const job=await request(`/api/jobs/${encodeURIComponent(id)}`);if(id!==currentJobId||token!==pollToken)return;pollErrors=0;showJob(job);await loadLog(id);if(!isTerminal(job.state))schedulePoll(token);else refreshHistory();}catch(error){if(token!==pollToken)return;pollErrors++;message('#job-message',`进度读取失败：${error.message}${pollErrors>=3?'；已暂停自动刷新，请点击“刷新任务”重试。':'；正在重试。'}`,true);if(pollErrors<3)schedulePoll(token);}},1800);}
async function loadLog(id){try{const text=await request(`/api/jobs/${encodeURIComponent(id)}/log`,{},true);if(currentJobId!==id)return;const node=$('#job-log'),bottom=node.scrollTop+node.clientHeight>=node.scrollHeight-50;let output=text;try{const data=JSON.parse(text);if(data.text!=null)output=data.text;else if(data.log!=null)output=data.log;}catch{}node.textContent=output||'任务尚未产生日志。';if(bottom)node.scrollTop=node.scrollHeight;}catch(error){if(currentJobId===id)$('#job-log').textContent=`日志暂不可读取：${error.message}`;}}
function showJob(job){currentJob=job;const name=job.spec?.case_name||job.case_name||job.id;$('#result-subtitle').textContent=`${job.kind==='pointcloud'?'实测点云处理':'腐蚀演化'} · ${name} · ${job.id}`;const badge=$('#result-state');badge.textContent=statuses[job.state]||job.state||'未知状态';badge.className=`badge ${job.state==='failed'?'failed':job.state==='running'?'running':isTerminal(job.state)?'':'neutral'}`;$('#elapsed-label').textContent=`运行耗时 ${elapsed(job)}`;const p=job.progress&&typeof job.progress==='object'?job.progress:job,result=job.result||{},done=p.stages_completed??job.stages_completed??result.stages_completed,total=p.total_stages??job.total_stages??result.total_stages;let percent=p.percent??p.percentage??job.percent;if(percent==null&&typeof job.progress==='number')percent=job.progress;if(percent==null&&total)percent=Number(done||0)/Number(total)*100;if(job.state==='completed')percent=100;const hasProgress=typeof percent==='number'&&Number.isFinite(percent);$('#progress-bar').style.width=`${hasProgress?Math.max(0,Math.min(100,percent)):0}%`;$('.progress-track').classList.toggle('indeterminate',!hasProgress&&!isTerminal(job.state));$('#progress-text').textContent=job.state==='failed'?job.error||'运行失败，请查看日志':`${statuses[job.state]||job.state}${total?` · 阶段 ${done??0} / ${total}`:''}`;const generation=p.generation??job.generation,maxgen=p.maxgen??job.maxgen;$('#progress-detail').textContent=[phases[p.phase||job.phase]||p.phase||job.phase,generation!=null?`迭代 ${generation}${maxgen?` / ${maxgen}`:''}`:'',p.stage!=null?`当前阶段 ${p.stage}`:'',job.error&&job.state!=='failed'?job.error:''].filter(Boolean).join(' · ')||'等待服务端报告进度';$('#stop-job').hidden=isTerminal(job.state)||!['running','queued','pending','created','stopping'].includes(job.state);$('#stop-job').disabled=job.state==='stopping';$('#resume-job').hidden=!isTerminal(job.state)||job.state==='completed'||!checkpointAvailable(job);$('#transfer-job').hidden=job.kind!=='pointcloud'||job.state!=='completed';$('#load-job-config').hidden=job.kind==='pointcloud'||!(job.effective_config||job.spec?.config);renderResult(job);}
function renderResult(job){const summary=job.summary||job.result?.summary||job.result||{},config=job.effective_config?.config||job.effective_config||job.spec?.config||{},backend=summary.actual_backend||job.actual_backend||job.progress?.actual_backend,seed=summary.seed??config.GA_CONFIG?.seed,provenance=summary.provenance||{},resourceEstimate=job.spec?.resource_estimate;let html=`<div class="card wide"><h3>本次计算信息</h3><div class="result-metadata"><div><small>实际计算后端</small><strong>${escape(backend||(job.kind==='pointcloud'&&job.state==='completed'?'MATLAB':'等待计算报告'))}</strong></div><div><small>随机种子</small><strong>${seed!=null?escape(seed):'—'}</strong></div><div><small>运行模式</small><strong>${escape(job.kind==='pointcloud'?'MATLAB':summary.mode||config.mode||'—')}</strong></div><div><small>检查点恢复</small><strong>${checkpointAvailable(job)?'可申请恢复':'暂不可用'}</strong></div></div>${renderTimings(summary.timing||summary.timings||job.timing||job.progress?.timing||summary)}${resourceEstimate?.memory_gib!=null?`<p class="help-line">资源估算：${format(resourceEstimate.memory_gib)} GiB；主进程观测峰值：${(summary.timing||job.timing||{}).peak_memory_bytes!=null?format((summary.timing||job.timing).peak_memory_bytes/1024**3)+" GiB":"待记录"}。估算不是内存上界，主进程观测值不含子进程和 GPU。</p>`:""}${summary.objective_rule?`<p class="help-line">${escape(summary.objective_rule)}</p>`:''}${summary.warnings?.length?`<div class="notice"><p>${summary.warnings.map(item=>escape(item)).join('<br>')}</p></div>`:''}${provenance.versions?`<p class="help-line">运行溯源：Python ${escape(provenance.versions.python||'—')} · NumPy ${escape(provenance.versions.numpy||'—')} · SciPy ${escape(provenance.versions.scipy||'—')} · Git ${escape(provenance.git_commit||'未读取')}</p>`:''}</div>`;
 if(job.kind==='pointcloud'){const values=summary.six_metrics||summary.metrics;html+=`<div class="card wide"><h3>实测六指标</h3>${Array.isArray(values)?`<div class="table-wrap"><table><thead><tr><th>物理指标</th><th>实测值</th><th>单位 / 定义</th></tr></thead><tbody>${metrics.map(([key,name,unit],index)=>`<tr><td>${name}</td><td>${format(values[index])}</td><td>${unit}</td></tr>`).join('')}</tbody></table></div>`:'<p class="preview">六指标尚未生成；部分运行文件仍可在下方下载。</p>'}${summary.calibration_ready!=null?`<div class="notice ${summary.calibration_ready?'':'error'}"><p>${summary.calibration_ready?'参考面和指标校核已通过，可转入模拟。':'指标尚未通过校核，请检查参考面、扫描方向和输出。'}${summary.calibration_issues?.length?'<br>'+summary.calibration_issues.map(escape).join('<br>'):''}</p></div>`:''}</div>`;}
 const stages=summary.stages||[];if(stages.length){html+=`<div class="card wide"><h3>阶段目标与实际形貌</h3><p class="preview">目标来自输入；实际值来自该阶段最终形貌。缺失或未定义的指标显示为“—”。</p>${stages.map(stage=>comparisonStage(stage)).join('')}</div>`;const traces=stages.filter(stage=>Array.isArray(stage.convergence)&&stage.convergence.length);if(traces.length)html+=`<div class="card wide"><h3>遗传算法收敛记录</h3><div class="legend"><span><i></i>加权综合误差</span><span>横轴：遗传代数</span></div>${traces.map(stage=>`<div class="stage-block"><h4>阶段 ${escape(stage.stage)}</h4>${convergenceChart(stage.convergence)}<p class="chart-caption">曲线仅绘制任务保存的实际迭代记录。</p></div>`).join('')}</div>`;else html+='<div class="card wide"><h3>遗传算法收敛记录</h3><p class="preview">本任务尚未提供逐代收敛数据。</p></div>';html+=`<div class="card wide"><h3>阶段最优参数与目标函数</h3>${stages.map(stage=>`<div class="stage-block"><h4>阶段 ${escape(stage.stage)} · ${escape(stage.generations??'—')} 代</h4><div class="table-wrap"><table><tbody>${Object.entries(stage.parameters||{}).map(([key,value])=>`<tr><td>${escape(key)}</td><td>${format(value)}</td></tr>`).join('')}</tbody></table></div><p class="help-line">四项 GA 误差：${(stage.four_errors||[]).map(value=>format(value)).join(' / ')||'尚未提供'}</p></div>`).join('')}</div>`;}
 const files=(job.files||[]).map(file=>typeof file==='string'?{name:file}:file),plots=files.filter(file=>/\.(png|jpe?g|webp|gif|svg)$/i.test(file.name));if(plots.length)html+=`<div class="card wide"><h3>科研图像预览</h3><div class="plot-grid">${plots.map(file=>`<figure><a href="${downloadUrl(job.id,file.name)}" target="_blank" rel="noopener"><img src="${downloadUrl(job.id,file.name)}" alt="任务计算图像：${escape(file.name)}" loading="lazy"></a><figcaption>${escape(file.name)}</figcaption></figure>`).join('')}</div></div>`;
 html+=`<div class="card wide"><div class="card-heading"><div><h3>任务文件</h3><p>数值结果、有效配置、日志与图像按服务端实际生成情况列出。</p></div><span class="badge neutral">${files.length} 个文件</span></div>${files.length?`<div class="file-list">${files.map(file=>`<div class="file-row"><span>${escape(file.name)}${(file.size??file.bytes)!=null?` <small class="muted">${format((file.size??file.bytes)/1024)} KB</small>`:''}</span><a href="${downloadUrl(job.id,file.name)}" download>下载 ↓</a></div>`).join('')}</div>`:'<p class="preview">尚无导出文件。计算期间请留意日志；任务失败时也可能保留部分数值结果。</p>'}</div>`;$('#result-content').innerHTML=html;}
function comparisonStage(stage){const target=stage.target||metrics.map(([key])=>stage.target_metrics?.[key]),actual=Array.isArray(stage.actual_metrics)?stage.actual_metrics:stage.actual_six_metrics||metrics.map(([key])=>stage.actual_metrics?.[key]);return `<div class="stage-block"><h4>阶段 ${escape(stage.stage)}</h4><div class="table-wrap"><table><thead><tr><th>物理指标</th><th>目标值</th><th>实际值</th><th>实际 − 目标</th><th>单位</th></tr></thead><tbody>${metrics.map(([key,name,unit],index)=>{const t=target?.[index],a=actual?.[index],delta=typeof t==='number'&&typeof a==='number'&&Number.isFinite(t)&&Number.isFinite(a)?a-t:null;return `<tr><td>${name}</td><td>${format(t)}</td><td title="${escape(stage.metric_notes?.[key]||'')}">${format(a)}</td><td>${format(delta)}</td><td>${unit}</td></tr>`;}).join('')}</tbody></table></div>${Object.keys(stage.metric_notes||{}).length?`<p class="help-line">${Object.entries(stage.metric_notes).map(([key,note])=>`${escape(metrics.find(item=>item[0]===key)?.[1]||key)}：${escape(note)}`).join('；')}</p>`:''}</div>`;}
function renderTimings(timings){const labels={reading_seconds:'读取输入',read_seconds:'读取输入',input_read_seconds:'读取输入',simulation_seconds:'腐蚀演化',total_seconds:'总耗时',matlab_seconds:'MATLAB 进程（含启动）',matlab_input_seconds:'MATLAB 输入读取',matlab_preprocess_seconds:'MATLAB 预处理',matlab_analysis_seconds:'形貌分析（含过程图）',matlab_numeric_export_seconds:'数值文件导出',matlab_plot_export_seconds:'图片导出',matlab_target_export_seconds:'六指标目标导出',matlab_total_seconds:'MATLAB 脚本总耗时',compute_seconds:'计算',computation_seconds:'计算',preprocessing_seconds:'点云预处理',export_seconds:'导出',plotting_seconds:'绘图',plot_seconds:'绘图',checkpoint_seconds:'检查点保存',numeric_export_seconds:'数值导出',final_export_seconds:'最终导出',peak_memory_bytes:'主进程峰值内存'},entries=Object.entries(timings||{}).filter(([key,value])=>typeof value==='number'&&(key.endsWith('_seconds')||key==='peak_memory_bytes'||key in labels));if(!entries.length)return '';return `<div class="timing-grid">${entries.map(([key,value])=>`<div><small>${escape(labels[key]||phases[key.replace('_seconds','')]||key)}</small><strong>${key==='peak_memory_bytes'?format(value/1024/1024)+' MB':seconds(value)}</strong></div>`).join('')}</div>`;}
function convergenceChart(trace){const rows=trace.map((row,index)=>{if(typeof row==='number')return {x:index+1,y:row};if(Array.isArray(row))return {x:row[0]??index+1,y:row[1]};return {x:row.generation??index+1,y:row.weighted_error??row.best_error??row.error};}).filter(row=>Number.isFinite(row.x)&&Number.isFinite(row.y));if(!rows.length)return '<p class="preview">没有可绘制的有限误差值。</p>';const width=760,height=225,left=65,right=25,top=20,bottom=40,minX=Math.min(...rows.map(row=>row.x)),maxX=Math.max(...rows.map(row=>row.x));let minY=Math.min(...rows.map(row=>row.y)),maxY=Math.max(...rows.map(row=>row.y));const margin=(maxY-minY)*.12||Math.max(Math.abs(maxY)*.1,0.01);minY-=margin;maxY+=margin;const x=value=>left+(value-minX)/(maxX-minX||1)*(width-left-right),y=value=>height-bottom-(value-minY)/(maxY-minY)*(height-top-bottom),points=rows.map(row=>`${x(row.x).toFixed(2)},${y(row.y).toFixed(2)}`).join(' ');return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${rows.length} 个实际迭代记录的加权误差收敛曲线">${[0,.25,.5,.75,1].map(ratio=>{const value=minY+(maxY-minY)*ratio,position=y(value);return `<path d="M${left} ${position}H${width-right}" stroke="#e8efdf"/><text x="${left-10}" y="${position+3}" font-size="9" fill="#78916b" text-anchor="end">${format(value,3)}</text>`;}).join('')}<path d="M${left} ${top}V${height-bottom}H${width-right}" stroke="#b9cdb0" fill="none"/><polyline points="${points}" fill="none" stroke="#26734e" stroke-width="2"/>${rows.length<50?rows.map(row=>`<circle cx="${x(row.x)}" cy="${y(row.y)}" r="2.5" fill="#26734e"><title>第${row.x}代：${row.y}</title></circle>`).join(''):''}<text x="${left}" y="${height-18}" fill="#78916b" font-size="10">${minX}</text><text x="${width-right}" y="${height-18}" text-anchor="end" fill="#78916b" font-size="10">${maxX}</text><text x="${width/2}" y="${height-5}" fill="#617b53" font-size="10" text-anchor="middle">遗传代数</text><text x="${left}" y="10" fill="#617b53" font-size="9">加权综合误差</text></svg>`;}
async function refreshBatchHistory(){let box=$('#batch-history');if(!box){box=document.createElement('div');box.id='batch-history';box.className='history-list';$('#history-list').before(box);}try{const batches=await request('/api/batches');box.hidden=!batches.length;box.innerHTML=batches.length?'<h3>批次记录</h3>'+batches.map(batch=>`<div class="history-item"><div class="history-info"><span class="history-type" aria-hidden="true">▦</span><div><strong>批次 ${escape(batch.id)}</strong><small>${(batch.job_ids||[]).length} 个工况 · ${escape(batch.run_mode||'—')} · 完成 ${batch.completed_count??0}</small></div></div><div class="history-actions"><span class="badge ${batch.state==='failed'?'failed':batch.state==='running'?'running':'neutral'}">${escape(statuses[batch.state]||batch.state)}</span><button class="button secondary" data-open-batch="${escape(batch.id)}">查看批次</button></div></div>`).join(''):'';box.querySelectorAll('[data-open-batch]').forEach(button=>button.addEventListener('click',()=>{currentBatchId=button.dataset.openBatch;activate('simulation-panel');$('.batch-card').open=true;pollBatch();$('.batch-card').scrollIntoView({block:'start'});}));}catch(error){box.innerHTML=`<div class="message error">批次记录读取失败：${escape(error.message)}</div>`;box.hidden=false;}}
async function refreshHistory(){try{const data=await request('/api/jobs'),jobs=Array.isArray(data)?data:data.jobs||[];$('#job-count').textContent=jobs.length;$('#history-list').innerHTML=jobs.length?jobs.map(job=>{const timestamp=typeof job.created_at==='number'?new Date(job.created_at*1000):new Date(job.created_at);return `<div class="history-item"><div class="history-info"><span class="history-type" aria-hidden="true">${job.kind==='pointcloud'?'◈':'▦'}</span><div><strong>${escape(job.spec?.case_name||job.case_name||(job.kind==='pointcloud'?'实测点云 → 六指标':'CA–GA 腐蚀演化'))}</strong><small>${Number.isNaN(timestamp.getTime())?'时间未提供':timestamp.toLocaleString('zh-CN')} · ${escape(job.id)}${job.elapsed_seconds!=null?' · '+seconds(job.elapsed_seconds):''}</small>${job.error?`<p class="error-hint">${escape(job.error).slice(0,220)}</p>`:''}</div></div><div class="history-actions"><span class="badge ${job.state==='failed'?'failed':job.state==='running'?'running':'neutral'}">${escape(statuses[job.state]||job.state)}</span><button class="button secondary" data-open="${escape(job.id)}">查看 →</button>${checkpointAvailable(job)&&isTerminal(job.state)&&job.state!=='completed'?`<button class="button ghost" data-resume="${escape(job.id)}">恢复</button>`:''}</div></div>`;}).join(''):'<div class="empty-state"><h3>还没有运行记录</h3><p>提交点云处理或腐蚀演化任务后，可在这里查看全过程。</p></div>';$('#history-list').querySelectorAll('[data-open]').forEach(button=>button.addEventListener('click',()=>openJob(button.dataset.open)));$('#history-list').querySelectorAll('[data-resume]').forEach(button=>button.addEventListener('click',busy(button,()=>controlJob('resume',button.dataset.resume))));await refreshBatchHistory();}catch(error){$('#history-list').innerHTML=`<div class="message error">运行记录读取失败：${escape(error.message)}。点击刷新重试。</div>`;}}
async function controlJob(action,id=currentJobId){if(!id)return;try{await post(`/api/jobs/${encodeURIComponent(id)}/${action}`);await openJob(id);message('#job-message',action==='stop'?'停止请求已发送，任务状态以服务端返回为准。':'恢复请求已提交；有效配置和随机状态由检查点恢复。');refreshHistory();}catch(error){message('#job-message',error.message,true);}}
async function transfer(){try{const result=await post(`/api/jobs/${encodeURIComponent(currentJobId)}/transfer`);applyTransfer(workspace,result);syncTargetSource();renderSimulation();const variable=$('#target-variable');variable.innerHTML=`<option value="${escape(workspace.targetVariable)}">${escape(workspace.targetVariable)}</option>`;variable.value=workspace.targetVariable;$('#target-preview').textContent=`来自点云任务 ${currentJobId}：${workspace.targets.length} 行实际六指标已载入，几何参数可在下方单独确认。`;activate('simulation-panel');message('#sim-message','已转入实际六指标。请确认参考面、指标单位、阶段方式和网格几何，再运行模拟。');invalidatePrecheck();}catch(error){message('#job-message',error.message,true);}}
function exportConfiguration(){collectSimulation(false);const blob=new Blob([JSON.stringify({config:workspace.simulation,run_mode:workspace.runMode,seed_mode:workspace.seedMode,targets:workspace.targets,pointcloud:workspace.pointcloud},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`corrosion-config-${new Date().toISOString().slice(0,10)}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('#sim-message','已导出当前完整模拟配置；目标矩阵与实际种子均包含在配置中。');}
async function refreshSyncStatus(){let panel=$('#sync-preview');if(!panel){panel=document.createElement('details');panel.id='sync-preview';panel.className='sync-preview';const summary=document.createElement('summary');summary.textContent='变更预览';summary.title='查看 GitHub 同步变更';const content=document.createElement('pre');panel.append(summary,content);$('#sync-button').after(panel);}try{const status=await request('/api/sync');const lines=[`分支：${status.branch||'未知'}`,`当前提交：${status.commit||'未知'}`,`待推送提交：${status.ahead_count??'未关联上游'}`,`待同步文件：${status.changed_count??0}`,status.changes||'（网站源码无本地改动）'];panel.querySelector('pre').textContent=lines.join('\n');panel.hidden=!status.available;panel.title=status.remote||'';}catch(error){panel.querySelector('pre').textContent=`同步状态读取失败：${error.message}`;panel.hidden=false;}}
