 $('#import-config').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{importSimulation(workspace,JSON.parse(await file.text()));if(workspace.simulation.MULTI_CASE_CONFIG?.cases)workspace.cases=clone(workspace.simulation.MULTI_CASE_CONFIG.cases);renderSimulation();renderCases();invalidatePrecheck();$('#target-preview').textContent=`目标来自导入配置 ${file.name}。`;message('#sim-message',`已载入完整配置 ${file.name}；请预检后提交。`);}catch(error){message('#sim-message',error.message,true);}finally{event.target.value='';}});$('#export-config').addEventListener('click',()=>{try{readBatchControls();if(workspace.cases.length)readCases();exportConfiguration();}catch(error){message('#sim-message',error.message,true);}});$('#apply-geometry').addEventListener('click',()=>{const supported=Object.keys(workspace.simulation.GEOMETRY_CONFIG),applied=[];for(const [key,value] of Object.entries(workspace.transferGeometry||{}))if(supported.includes(key)&&typeof value==='number'&&Number.isFinite(value)){workspace.simulation.GEOMETRY_CONFIG[key]=value;applied.push(key);}renderCatalog('simulation');invalidatePrecheck();message('#sim-message',applied.length?`已采用几何参数：${applied.join('、')}。请再次复核网格尺寸和层间距。`:'转入信息没有与模拟几何同名的数值参数，请手动设置网格分辨率。');});
