 for(const id of ['#batch-mode','#parallel-case-workers','#sequential-enabled','#parallel-enabled'])$(id).addEventListener('change',()=>{try{readBatchControls();syncBatchConfig();renderCatalog('simulation');invalidatePrecheck();}catch(error){message('#sim-message',error.message,true);}});updateBatchAvailability();
