$('#sync-button').addEventListener('click',busy($('#sync-button'),async()=>{message('#global-message','正在同步网站源码…');try{await refreshSyncStatus();const result=await post('/api/sync'),outcome=result.message||result.output||result.stdout||readable(result);message('#global-message',`网站源码同步结果：\n${outcome}${result.branch?'\n分支：'+result.branch:''}${result.commit?'\n提交：'+result.commit:''}${result.output?'\n'+result.output:''}`,result.success===false||result.ok===false);await refreshSyncStatus();}catch(error){message('#global-message',`同步失败：${error.message}`,true);}}));
